"""Manually authored row dispositions. Run from the repository root."""
import collections
import json
import re
from pathlib import Path

L = Path(__file__).parent
rows = json.loads((L / 'CURRENT_ROW_INVENTORY.json' if (L / 'CURRENT_ROW_INVENTORY.json').exists() else L / 'ROW_INVENTORY.json').read_text())
by_code = {r['code']: r for r in rows}
mapping = {}
N = 'docs/LIFE_SIM_NORTH_STAR.md'
C = 'docs/CHEAT_LIBRARY.md'
CO = 'docs/CHEAT_COSMOLOGY.md'
TI = 'docs/TIMELINES_AND_DIVERGENCE.md'
TK = 'docs/TIME_KEEPERS_AND_VARIANTS.md'
SE = 'docs/SELVES_AND_ECHOES.md'
RE = 'docs/research/DEATH_AND_RESET_CONSIDERATIONS_2026-10-10.md'
PA = 'docs/STARTS_ENDINGS_AND_RANDOMNESS_PALETTE.md'
PS = 'docs/PROCEDURAL_STORY_AND_CONTENT_CONSIDERATIONS_2026-10-14.md'
WD = 'docs/worlds/world-depth-2026-10-13/'
W = 'docs/worlds/'
EM = 'docs/emergent/'
RULE = 'docs/RULES_FROM_SCRATCH.md'

def expand(s):
    result = []
    for token in s.split():
        m = re.fullmatch(r'([A-Z]+)(\d+)\.\.(\d+)', token)
        result.extend([f'{m[1]}{i}' for i in range(int(m[2]), int(m[3])+1)] if m else [token])
    return result

def put(codes, path, line, relation, why, action=None):
    for code in expand(codes):
        assert code in by_code, code
        assert code not in mapping, ('duplicate mapping', code)
        mapping[code] = {'owner': path, 'owner_line': line, 'relation': relation,
                         'reason': why, 'action': action or ('cite instead' if relation == 'duplicate' else 'keep as refinement')}

def dup(codes, path, line, why):
    put(codes, path, line, 'duplicate', why)

def ref(codes, path, line, why):
    put(codes, path, line, 'refines', why)

def conflict(codes, path, line, why):
    put(codes, path, line, 'contradicts', why, 'flag for Weibao; integrator can correct clear authority conflicts')

