def revise(code, path, line, relation=None, reason=None):
    old = mapping[code]
    old['owner'], old['owner_line'] = path, line
    if relation:
        old['relation'] = relation
        old['action'] = {'duplicate': 'cite instead', 'refines': 'keep as refinement',
                         'contradicts': 'flag for Weibao; integrator can correct clear authority conflicts',
                         'no demonstrated overlap': 'keep pending integration'}[relation]
    if reason:
        old['reason'] = reason

